layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); border-left: 4px solid var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: italic; line-height: 1.5; letter-spacing: 0.96px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 16px; padding-bottom: 0px; padding-left: 16px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: 0.96px; text-transform: none }
article[data-ryt="rec-card"] { border-bottom: 1px dashed rgb(125, 130, 138); border-radius: 0px; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-text); border-radius: 0px; box-shadow: rgb(1, 132, 114) 0px -4px 0px 0px inset; font-weight: 400; font-style: normal; letter-spacing: 0.96px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: box-shadow 0.3s }
[data-ryt="category"], [data-ryt="tags"] li { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; line-height: normal; letter-spacing: 0.96px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: color 0.4s ease-out }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 12.8px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: 0.96px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 14.4px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="section"] > h2 { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 1.5; letter-spacing: 0.96px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: 0.96px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.4s ease-out }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 23.04px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: 0.96px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.4s ease-out }
[data-ryt="header"] { box-shadow: rgba(0, 0, 0, 0.45) -1px -2px 3px 0px }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: 0.96px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: color 0.4s ease-out }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: 0.96px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a:hover { color: rgb(255, 255, 255); text-shadow: rgb(255, 255, 255) 0px 0px 1px }
[data-ryt="brand"]:hover { color: rgb(255, 255, 255); text-shadow: rgb(255, 255, 255) 0px 0px 1px }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: rgb(255, 255, 255); text-shadow: rgb(255, 255, 255) 0px 0px 1px }
[data-ryt="category"]:hover, [data-ryt="tags"] li:hover { color: rgb(255, 255, 255); text-shadow: rgb(255, 255, 255) 0px 0px 1px; border-bottom-width: 1px; border-bottom-style: solid; border-bottom-color: rgb(1, 132, 114) }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: rgb(255, 255, 255); text-shadow: rgb(255, 255, 255) 0px 0px 1px; box-shadow: rgb(1, 132, 114) 0px calc(-1.5em - 5px) inset }
